window.getPublicResources = (levelId, subject, topic) => {
  const items = competitionCatalog[levelId + "::" + subject];
  if (!items) return null;
  const isExhibition = subject.includes('科展');
  const showExternal = (levelId === 'senior-gifted' && (subject === 'AMC 10／12 與 AIME' || subject === '清華盃高中化學科能力競賽' || subject.startsWith('學科能力競賽｜'))) || levelId === 'junior-gifted' || (levelId === 'junior' && subject === '會考歷屆') || (levelId === 'senior' && subject === '學測／分科歷屆');
  let scopedItems = items;
  if (levelId === 'senior-gifted' && subject === '數學奧林匹亞 TMO／IMO、APMO、EGMO' && topic) {
    const match = topic.startsWith('APMO') ? 'APMO' : topic.startsWith('EGMO') ? 'EGMO' : 'TMO';
    scopedItems = items.filter(item => item.title.includes(match) || (match === 'TMO' && item.title.includes('IMO')));
  }
  if (levelId === 'senior-gifted' && subject === '生物奧林匹亞' && topic) {
    const match = topic === '初賽' ? '｜初賽｜' : topic === '複賽' ? '｜複賽｜' : topic === '選拔營' ? '｜選拔營｜' : topic === '國際賽實作' ? '｜國際賽實作｜' : '｜國際賽理論｜';
    scopedItems = items.filter(item => item.title.includes(match) || item.title.includes('｜' + topic + '官方頁面'));
  }
  if (levelId === 'senior' && subject === '學測／分科歷屆' && topic) {
    const match = topic.startsWith('學科能力') ? '學科能力' : '分科測驗';
    scopedItems = items.filter(item => item.title.includes(match));
  }
  if (levelId === 'senior-gifted' && subject.startsWith('學科能力競賽｜') && topic) {
    const isSchool = topic === '校內初選';
    const isRegional = topic === '分區複賽';
    const isFinal = topic === '全國決賽';
    scopedItems = items.filter(item => {
      const title = item.title || '';
      const generic = !/(校內|初選|區|複賽|全國|決賽)/.test(title);
      if (isSchool) return /校內|初選/.test(title);
      if (isRegional) return /區|複賽/.test(title) || generic;
      if (isFinal) return /全國|決賽/.test(title) || generic;
      return true;
    });
  }
  if (levelId === 'junior-gifted' && subject === 'AMC 8／AMC 10' && topic) {
    const match = topic.startsWith('AMC 8') ? 'AMC 8' : topic.includes('10A') ? 'AMC 10A' : topic.includes('10B') ? 'AMC 10B' : '';
    if (match) scopedItems = items.filter(item => item.title.includes(match) || item.title.includes('MAA American Mathematics Competitions'));
  }
  if (levelId === 'junior-gifted' && subject === '張進通許世賢國中數學能力競試' && topic) {
    const year = topic.match(/\d{2,3}/)?.[0] || '';
    if (year) scopedItems = items.filter(item => item.title.includes(year));
  }
  const pdfItems = showExternal || isExhibition
    ? scopedItems
    : scopedItems.filter(item => /\.pdf(?:$|[?#])/i.test(item.file || item.url || ''));
  return pdfItems.length ? { title: topic ? subject + '｜' + topic + '官方資源' : subject + '官方資源', items: pdfItems } : null;
};